@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity_in_stock : float
}

class Dish {
  + name : string
  + numeric_identifier : int
}

class IngredientDish {
  + quantity : float
}

class Table {
  + numeric_identifier : int
  + maximum_ammount_of_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class DishMeal {
  + times_served : int
}

class Waiter {
  + numerical_identifier : int
  + name : string
  + address : string
  + phone_number : string
}

class Client {
  + tax_identification_number : string
  + name : string
  + address : string
}

Dish "*" -- "*" Ingredient : composed of
DishMeal "*" -- "1" Dish
DishMeal "*" -- "1" Meal

Meal "*" -- "1" Table
Meal "*" -- "0..1" Client
Meal "*" -- "1" Waiter

@enduml

